  "query": "SELECT pv.pvid AS payment_voucher_id, pv.pvnotransaksi AS nomor_payment_voucher, pv.pvtgl AS tanggal_payment_voucher, c.knama AS nama_customer, sr.srid AS sales_return_id, sr.srnotransaksi AS nomor_sales_return, sr.srtgl AS tanggal_sales_return, pvd.totaltransaksi AS total_sales_return, pvd.terbayar AS total_terbayar_sebelumnya, pvd.jmlbayar AS jumlah_dibayar, pvd.diskontermin AS diskon_termin, pvd.jmldiskontermin AS jumlah_diskon_termin, pvd.sisa AS sisa_transaksi, pv.pvstatus AS status_payment_voucher FROM m5_pv AS pv INNER JOIN m5_pv_detail AS pvd ON pvd.idpv = pv.pvid INNER JOIN m5_sr AS sr ON pvd.sumber = 'SR' AND pvd.idtransaksi = sr.srid LEFT JOIN m1_contact AS c ON pv.pvcustomer = c.kid AND c.kaktif = 1 WHERE pvd.sumber = 'SR' ORDER BY pv.pvtgl DESC, pv.pvnotransaksi DESC LIMIT 100",
