  "query": "SELECT s.sieid AS id_tukar_faktur, s.sienotransaksi AS no_tukar_faktur, s.sietgl AS tgl_tukar_faktur, sd.idsiedetail AS id_detail_tukar_faktur, sd.sumber AS tipe_dokumen_sumber, CASE WHEN sd.sumber = 'SI' THEN si.siinotransaksi ELSE NULL END AS no_invoice_sumber, CASE WHEN sd.sumber = 'SI' THEN si.sitgl ELSE NULL END AS tgl_invoice_sumber, CASE WHEN sd.sumber = 'SR' THEN sr.srnotransaksi ELSE NULL END AS no_retur_sumber, CASE WHEN sd.sumber = 'SR' THEN sr.srtgl ELSE NULL END AS tgl_retur_sumber, sd.catatan AS catatan_detail_sumber FROM m5_sie AS s INNER JOIN m5_sie_detail AS sd ON sd.idsie = s.sieid LEFT JOIN m5_si AS si ON sd.sumber = 'SI' AND sd.idtransaksi = si.siid LEFT JOIN m5_sr AS sr ON sd.sumber = 'SR' AND sd.idtransaksi = sr.srid ORDER BY s.sietgl DESC, s.sienotransaksi DESC, sd.urutan ASC LIMIT 100",
